import {validateSave,newSave} from './frontier.mjs';
export const PRE_EXPLORATION_KEY='farbound-save-pre-2.1';
export const SAVE_KEY='farbound-save-v2',BACKUP_KEY='farbound-save-v2-checkpoint',ORIGINAL_KEY='farbound-save-v1';
const parse=raw=>{try{return JSON.parse(raw);}catch{return null;}};
export function readPilot(storage){try{const raw=storage.getItem(SAVE_KEY),parsed=parse(raw),pilot=validateSave(parsed);if(pilot&&parsed.systemScans===undefined&&!storage.getItem(PRE_EXPLORATION_KEY)){try{storage.setItem(PRE_EXPLORATION_KEY,raw);}catch{return{pilot,existing:true,error:true};}}if(pilot)return{pilot,existing:true};const checkpoint=validateSave(parse(storage.getItem(BACKUP_KEY))?.pilot);if(checkpoint)return{pilot:checkpoint,existing:true,recovered:true};const original=storage.getItem(ORIGINAL_KEY),v1=validateSave(parse(original));if(v1){if(!storage.getItem('farbound-original-backup'))storage.setItem('farbound-original-backup',original);return{pilot:v1,existing:true,migrated:true};}if(raw&&!storage.getItem('farbound-unreadable-save'))storage.setItem('farbound-unreadable-save',raw);return{pilot:newSave(),existing:false,error:!!raw};}catch{return{pilot:newSave(),existing:false,error:true};}}
export function writePilot(storage,pilot,{checkpoint=false,now=Date.now()}={}){const old=storage.getItem(SAVE_KEY),previous=parse(storage.getItem(BACKUP_KEY));if(old&&parse(old)?.systemScans===undefined&&validateSave(parse(old))&&!storage.getItem(PRE_EXPLORATION_KEY))storage.setItem(PRE_EXPLORATION_KEY,old);if(old&&(checkpoint||!previous||now-previous.at>180000)&&validateSave(parse(old)))storage.setItem(BACKUP_KEY,JSON.stringify({at:now,pilot:parse(old)}));storage.setItem(SAVE_KEY,JSON.stringify(pilot));}
export function readCheckpoint(storage){try{const p=parse(storage.getItem(BACKUP_KEY)),pilot=validateSave(p?.pilot);return pilot?{at:p.at,pilot}:null;}catch{return null;}}
